import { copyFileSync } from "node:fs";
import { join } from "node:path";

// The image is generated by an AI image model; this program only copies it
// to the output directory so the competition runner can score it.
copyFileSync(
  new URL("./entry.png", import.meta.url),
  join(process.env.MAKEFUN_OUTPUT_DIR ?? "/output", "entry.png"),
);
